import { styled } from '@hexa-ui/theme';

export const StyledOverviewRoot = styled('div', {
  boxSizing: 'border-box',
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  width: '100%',
  margin: 0,
  padding: 0,

  '& [data-testid$="-performance-title"], & [data-testid$="-portfolio-title"]':
    {
      fontFamily: '$heading',
      fontSize: '32px',
      lineHeight: '120%',
    },
});
